import {isConfigured,signIn,signOut,listRows,saveRow,uploadImage,request} from './data/supabase.js';
import {contentFields,loadContent} from './data/content.js';
const $=s=>document.querySelector(s);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let rows=[],editing=null,tab='products',busy=false,dirty=false,generation=0;
const message=text=>{$('#message').textContent=text;};
const error=e=>message(e.message || 'Не удалось выполнить операцию.');
function resetWorkspace(){dirty=false;generation++;rows=[];editing=null;$('#workspace-body').replaceChildren();$('#workspace').hidden=true;$('#login-panel').hidden=false;$('#logout').hidden=true;$('#editor').close();$('#product-form').reset();}
if(!isConfigured()){message('Подключение Supabase ещё не настроено.');$('#login button').disabled=true;}
$('#login').addEventListener('submit',async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;message('Входим…');const data=new FormData(e.currentTarget);try{await signIn(data.get('email'),data.get('password'));e.target.reset();$('#login-panel').hidden=true;$('#workspace').hidden=false;$('#logout').hidden=false;await showTab('products');}catch(e){error(e);}finally{button.disabled=false;}});
$('#logout').onclick=async()=>{try{await signOut();}catch{}finally{resetWorkspace();message('Вы вышли из аккаунта.');}};
document.querySelectorAll('[data-tab]').forEach(button=>button.onclick=()=>showTab(button.dataset.tab));
async function showTab(next){const current=++generation;tab=next;document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.tab===tab)));$('#workspace-body').innerHTML='<p>Загрузка…</p>';message('');try{if(tab==='products'){const loaded=await listRows(true);if(current!==generation)return;rows=loaded;renderProducts();}else if(tab==='bookings'){const bookings=await request('/rest/v1/optika_bookings?select=*&order=created_at.desc&limit=500',{authenticated:true});if(current!==generation)return;renderBookings(bookings);}else{const content=await loadContent();if(current!==generation)return;renderContent(content);}}catch(e){if(current===generation){$('#workspace-body').innerHTML='<button id="retry">Повторить загрузку</button>';$('#retry').onclick=()=>showTab(tab);error(e);}}}
function renderProducts(){
 $('#workspace-body').innerHTML='<div class="heading"><div><h1>Коллекция</h1><p class="count">'+rows.length+' товаров · изменения сохраняются в Supabase</p></div><button class="primary" id="new-product">Добавить товар</button></div><div class="toolbar"><input id="product-search" type="search" placeholder="Найти бренд или модель" aria-label="Поиск товаров"><button id="refresh">Обновить</button></div><div id="product-list"></div>';
 $('#new-product').onclick=()=>editProduct(null);$('#refresh').onclick=()=>showTab('products');$('#product-search').oninput=renderList;renderList();
}
function renderList(){const q=$('#product-search').value.toLocaleLowerCase('ru');const filtered=rows.filter(r=>`${r.data.brand} ${r.data.model}`.toLocaleLowerCase('ru').includes(q));$('#product-list').innerHTML=filtered.length?'<div class="table-wrap"><table><thead><tr><th>Модель</th><th>Цена</th><th>Видимость</th><th>Действие</th></tr></thead><tbody>'+filtered.map(r=>`<tr><td><strong>${esc(r.data.brand)}</strong>${esc(r.data.model)}</td><td>${Number(r.data.price).toLocaleString('ru-RU')} ₽</td><td><span class="badge">${r.published?'В каталоге':'Скрыт'}</span></td><td><button data-edit="${esc(r.id)}">Изменить</button></td></tr>`).join('')+'</tbody></table></div>':'<p class="empty">Товары не найдены. Добавьте первую модель.</p>';document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editProduct(rows.find(r=>r.id===b.dataset.edit)));}
const field=name=>$('#product-form').elements.namedItem(name);
function editProduct(row){editing=row;dirty=false;$('#product-form').reset();$('#editor-message').textContent='';$('#editor-title').textContent=row?'Редактирование товара':'Новый товар';const p=row?.data||{};for(const key of ['brand','model','category','gender','price','oldPrice','shortDescription','description','popularity'])if(p[key]!=null)field(key).value=p[key];field('slug').value=row?.slug||'';field('images').value=(p.images||[]).map(i=>i.src).join('\n');for(const key of ['isFeatured','isNew','isMock'])field(key).checked=!!p[key];field('published').checked=!!row?.published;for(const [key,label] of [['shape','Форма'],['color','Цвет'],['material','Материал оправы']])field(key).value=p.attributes?.[label]||'';$('#editor').showModal();}
function closeEditor(){if(busy)return;if(dirty&&!confirm('Закрыть без сохранения изменений?'))return;dirty=false;$('#editor').close();}
$('#close-editor').onclick=closeEditor;$('#cancel-editor').onclick=closeEditor;$('#editor').addEventListener('cancel',e=>{e.preventDefault();closeEditor();});$('#product-form').addEventListener('input',()=>dirty=true);
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
function setBusy(value){busy=value;$('#product-form').querySelectorAll('button,input,textarea,select').forEach(el=>el.disabled=value);}
$('#upload').onchange=async e=>{const file=e.target.files[0];if(!file)return;setBusy(true);$('#editor-message').textContent='Загружаем фотографию…';try{const url=await uploadImage(file);field('images').value=[field('images').value.trim(),url].filter(Boolean).join('\n');dirty=true;$('#editor-message').textContent='Фотография загружена. Сохраните товар, чтобы добавить её в карточку.';}catch(e){$('#editor-message').textContent=e.message;}finally{setBusy(false);$('#upload').value='';}};
$('#product-form').onsubmit=async e=>{e.preventDefault();if(busy||!e.target.reportValidity())return;const d=new FormData(e.target),value=k=>String(d.get(k)||'').trim();const images=value('images').split('\n').map(s=>s.trim()).filter(Boolean);if(images.length<1||images.length>12||images.some(s=>!/^https:\/\/[^\s]+$/.test(s)&&!/^\/assets\/[^\s]+$/.test(s))){$('#editor-message').textContent='Укажите от 1 до 12 адресов HTTPS или /assets/…';return;}if(value('oldPrice')&&Number(value('oldPrice'))<=Number(value('price'))){$('#editor-message').textContent='Старая цена должна быть больше текущей.';return;}
 const data={...editing?.data,brand:value('brand'),model:value('model'),category:value('category'),gender:value('gender'),price:Number(value('price')),oldPrice:value('oldPrice')?Number(value('oldPrice')):null,shortDescription:value('shortDescription'),description:value('description'),popularity:Number(value('popularity')),isFeatured:d.has('isFeatured'),isNew:d.has('isNew'),isMock:d.has('isMock'),images:images.map(src=>({src,alt:`${value('brand')} ${value('model')}`})),attributes:{...editing?.data.attributes,'Форма':value('shape'),'Цвет':value('color'),'Материал оправы':value('material')}};
 setBusy(true);$('#editor-message').textContent='Сохраняем…';try{await saveRow({id:editing?.id||crypto.randomUUID(),slug:value('slug'),published:d.has('published'),data},editing?.updated_at);dirty=false;$('#editor').close();await showTab('products');message('Товар сохранён. Витрина обновится при следующем открытии.');}catch(e){$('#editor-message').textContent=e.message;}finally{setBusy(false);}};
function renderBookings(bookings){$('#workspace-body').innerHTML='<div class="heading"><div><h1>Заявки на проверку зрения</h1><p class="count">Последние 500 заявок · '+bookings.filter(b=>b.status==='new').length+' новых</p></div><button id="refresh">Обновить</button></div>'+(bookings.length?'<div class="table-wrap"><table><thead><tr><th>Дата</th><th>Имя</th><th>Телефон</th><th>Статус</th></tr></thead><tbody>'+bookings.map(b=>`<tr><td>${esc(new Date(b.created_at).toLocaleString('ru-RU'))}</td><td>${esc(b.name)}</td><td><a href="tel:${esc(b.phone)}">${esc(b.phone)}</a></td><td><select class="status-select" aria-label="Статус заявки ${esc(b.name)}" data-status="${esc(b.id)}" data-current="${esc(b.status)}">${[['new','Новая'],['contacted','Связались'],['closed','Закрыта']].map(([value,label])=>`<option value="${value}" ${b.status===value?'selected':''}>${label}</option>`).join('')}</select></td></tr>`).join('')+'</tbody></table></div>':'<p class="empty panel">Заявок пока нет.</p>');$('#refresh').onclick=()=>showTab('bookings');document.querySelectorAll('[data-status]').forEach(select=>select.onchange=async()=>{select.disabled=true;try{const result=await request(`/rest/v1/optika_bookings?id=eq.${encodeURIComponent(select.dataset.status)}&status=eq.${encodeURIComponent(select.dataset.current)}`,{method:'PATCH',authenticated:true,body:{status:select.value},headers:{Prefer:'return=representation'}});if(!result.length)throw new Error('Статус уже изменён. Обновите список.');select.dataset.current=select.value;message('Статус заявки сохранён.');}catch(e){select.value=select.dataset.current;error(e);}finally{select.disabled=false;}});}
function renderContent(row){$('#workspace-body').innerHTML='<div class="heading"><div><h1>Главная страница</h1><p class="count">Основные заголовки и описания. Пустое поле оставляет исходный текст.</p></div></div><form id="content-form" class="panel content-form">'+contentFields.map(([key,label,,max])=>`<label>${esc(label)}<textarea name="${key}" maxlength="${max}">${esc(row?.data[key]||'')}</textarea></label>`).join('')+'<button class="primary">Сохранить тексты</button></form>';$('#content-form').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('button');button.disabled=true;const data=Object.fromEntries(new FormData(form));try{const path=row?`/rest/v1/optika_content?id=eq.homepage&updated_at=eq.${encodeURIComponent(row.updated_at)}`:'/rest/v1/optika_content';const saved=await request(path,{method:row?'PATCH':'POST',authenticated:true,body:{id:'homepage',data},headers:{Prefer:'return=representation'}});if(!saved.length)throw new Error('Тексты уже изменены в другом окне. Обновите раздел.');row=saved[0];message('Тексты главной страницы сохранены.');}catch(e){error(e);}finally{button.disabled=false;}};}

